import{e as t}from"./form_types-CDdbkj6v.js";const a=[{id:"aopt:framing_POVs_enabled",defn:'Enable framing notes from selected "POV" labels. "version" is the only POV label never enabled for AI estimators; used for notes about work-in-progress judgement problems, and for argument source attribution that would eagerly welcome bias via familiarity with the argument from pretraining.',default_value:["math-help","version","meta","clarification","author_estimate","LL","ZW"],allowed_values:["math-help","version","meta","clarification","author_estimate","LL","ZW"],input_type:"MultiStringFromSet",variant_producing:!0},{id:"aopt:srcquotes_inlined",defn:"Whether the source quotes (passages the definitions and framing notes were derived from) are part of the main text. When true, each quote is shown inline beneath the definition or note it grounds. When false, the quotes are not part of the text you estimate against (in the web interactive view they remain reachable on demand).",default_value:!0,variant_producing:!0,allowed_values:[!0,!1],input_type:"Bool"}],i={localStorage_prefix:"mcovidB8",conclusion_expr:"expr:pLL_givenLLorZW",conclusion_form:"form:fPLL",conclusion_type_highlevel:"probability",preamble_variant:"explicit_redirection_plus_encourage_plus_deemphasize"},o=["logOddsPrior","pZW_sarb","pZW_wuhan","LR_marketPhylo","pZW_noHost","LR_preadapt","LR_cggcggAndRePattern"],n=[{id:"svar:logOddsPrior",type_highlevel:"logodds",type_mathlevel:"open_real_interval",type_detail:{range:[null,null]},defn:"Before considering any of the specific evidence below, what is your prior on the origin being lab-related rather than wildlife zoonosis, expressed in log-odds? For example, -15 corresponds to odds of zoonosis being over 3 million times more likely a priori (not suggested by anyone serious); 0 is even odds; positive values favor lab origin."},{id:"svar:pZW_sarb",type_highlevel:"probability",type_mathlevel:"closed_real_interval",type_detail:{range:[0,1]},defn:"Under wildlife zoonosis, what is your probability that a new pandemic pathogen emerging in the region would be a sarbecovirus?"},{id:"svar:pZW_wuhan",type_highlevel:"probability",type_mathlevel:"closed_real_interval",type_detail:{range:[0,1]},defn:"Under wildlife zoonosis, and given that the pathogen is a sarbecovirus, what is your probability that its first human spread would be in Wuhan specifically?"},{id:"svar:LR_marketPhylo",type_highlevel:"oddsratio",type_mathlevel:"right_open_real_interval",type_detail:{range:[0,null]},defn:"How many times more likely is the combined market-clustering-and-phylogenetic evidence [MarketPhylo] under DEFUSE-style lab origin than under wildlife zoonosis? A value below 1 favors zoonosis; above 1 favors lab origin; 1 is non-diagnostic."},{id:"svar:pZW_noHost",type_highlevel:"probability",type_mathlevel:"closed_real_interval",type_detail:{range:[0,1]},defn:"Under wildlife zoonosis, what is your probability that no intermediate wildlife host would be found despite extensive sampling?"},{id:"svar:LR_preadapt",type_highlevel:"oddsratio",type_mathlevel:"right_open_real_interval",type_detail:{range:[0,null]},defn:"How many times more likely are the observed human-preadaptation features under lab origin than under wildlife zoonosis? A value of 1 is non-diagnostic; greater than 1 favors lab origin."},{id:"svar:LR_cggcggAndRePattern",type_highlevel:"oddsratio",type_mathlevel:"right_open_real_interval",type_detail:{range:[0,null]},defn:"Considering the CGG-CGG arginine codon pattern [CGGCGG] and the six-segment restriction-enzyme pattern [REpattern] together as a single body of sequence-design evidence — since both bear on the same underlying question of whether the genome shows signs of deliberate design, and your assessment of one plausibly informs the other — how many times more likely is this combined evidence under lab origin than under wildlife zoonosis?"}],r=[{id:"tchoice:agreeMarketPhyloDiscount",response_kind:"enum",defn:"You agree with the author's assessment that, once proximity-based ascertainment bias and the identified mathematical/coding errors in Pekar et al. are corrected for, the market-clustering and two-lineage phylogenetic evidence provides little to no net evidential weight favoring zoonosis over lab origin specifically. Choose false if you disagree — for example if you find Worobey et al.'s or Pekar et al.'s original analyses more credible than the author's rebuttals, or you weight institutional/peer-review consensus over a single-author critique more heavily than the author does. This choice does not affect your numeric estimates or the computed conclusion; it is recorded for the designer's own calibration.",default_value:!0,allowed_values:[!1,!0],input_type:"Bool"}],s={sections:{html:[{chunkid:"textchunk:title",style:"title"},{chunkid:"textchunk:subtitle",style:"subtitle"},{chunkid:"textchunk:ai_gen",style:"warning"},{chunkid:"textchunk:no_endorse",style:"warning"},{delegation_id:"FRAMING_EXPLAINER"},{delegation_id:"SRCQUOTE_EXPLAINER"},{delegation_id:"VISIBLE_AOPTS",header:"Problem Config"},{delegation_id:"FRAMING_ROOT",header:"Framing"},{delegation_id:"CPARAMS_SECTION"},{delegation_id:"TEXT_DEFINITIONS",header:"Text Definitions"},{delegation_id:"INTERPRETED_SYMBOL_SEMANTICS",header:"Interpreted Symbols"},{delegation_id:"DEFINED_SYMBOLS",header:"Defined Symbols"},{delegation_id:"AXIOMS",header:"Axioms"},{delegation_id:"SIMPLIFYING_ASSUMPTIONS",header:"Simplifying Assumptions"},{delegation_id:"TCHOICE",header:"Choices"},{delegation_id:"SVARS",header:"Estimation"},{delegation_id:"COMPUTED_FORMULAS",header:"Formulas"},{delegation_id:"CALCULATOR",subentries:["WHOSE_TOGGLE","CALCULATOR_INPUT","DERIVED_FORMS","CALCULATOR_RESULTS","YOURS_CODE_INPUT","JOINT_DEPENDENCE_EDITOR","YOURS_SAVED_LIST"],header:"Calculator"}],md:[{chunkid:"textchunk:title",style:"title"},{chunkid:"textchunk:subtitle",style:"subtitle"},{chunkid:"textchunk:ai_gen",style:"warning"},{chunkid:"textchunk:no_endorse",style:"warning"},{delegation_id:"FRAMING_EXPLAINER"},{delegation_id:"SRCQUOTE_EXPLAINER"},{delegation_id:"VISIBLE_AOPTS",header:"Problem Config"},{delegation_id:"FRAMING_ROOT",header:"Framing"},{delegation_id:"CPARAMS_SECTION"},{delegation_id:"TEXT_DEFINITIONS",header:"Text Definitions"},{delegation_id:"INTERPRETED_SYMBOL_SEMANTICS",header:"Interpreted Symbols"},{delegation_id:"DEFINED_SYMBOLS",header:"Defined Symbols"},{delegation_id:"AXIOMS",header:"Axioms"},{delegation_id:"SIMPLIFYING_ASSUMPTIONS",header:"Simplifying Assumptions"},{delegation_id:"TCHOICE",header:"Choices"},{delegation_id:"SVARS",header:"Estimation"},{delegation_id:"COMPUTED_FORMULAS",header:"Formulas"}]}},l=[{id:"textchunk:title",defn:"SARS-CoV-2 origin: lab leak vs wildlife zoonosis: v8"},{id:"textchunk:ai_gen",defn:"This judgement problem is AI-GENERATED (primarily Opus 4.8, with some math effort from Fable 5) with some input from Dustin Wehr. Much of the text is NOT REVIEWED YET BY A HUMAN."},{id:"textchunk:subtitle",defn:'A Bayesian odds analysis: an exposition without endorsement of ‹OMITTED to mitigate AI estimator contamination; attribution available in a "version" framing note, webapp only›. Starting from prior odds on two non-exhaustive origin hypotheses, a chain of roughly independent (but independence not assumed) likelihood factors updates to a posterior probability that the origin was a genetically-modified lab-leak ([LL]) rather than wildlife zoonosis ([ZW]).'},{id:"textchunk:no_endorse",defn:"THIS EXPOSITION IS NOT ENDORSED BY the original argument's author."},{id:"textchunk:draftnote",defn:"This is a pre-publication draft. Please don't circulate."}],d={expr:{"expr:logOddsPrior":"ln([priorOdds])","expr:oddsPrior":"[priorOdds]","expr:pZW_sarb":"P([Sarb]|[ZW])","expr:pZW_wuhan":"P([Wuhan]|[Sarb],[ZW])","expr:LR_marketPhylo":"[LR]([MarketPhylo], [Sarb], [Wuhan])","expr:pZW_noHost":"P([NoHost]|[Sarb],[Wuhan],[MarketPhylo],[ZW])","expr:LR_preadapt":"[LR]([Preadapt], [Sarb], [Wuhan], [MarketPhylo], [NoHost])","expr:LR_cggcggAndRePattern":"[LR]([cggcggAndRePattern], [Sarb], [Wuhan], [MarketPhylo], [NoHost], [Preadapt], [FCS])","expr:pLL_sarb":"P([Sarb]|[LL])","expr:pLL_wuhan":"P([Wuhan]|[Sarb],[LL])","expr:pLL_noHost":"P([NoHost]|[Sarb],[Wuhan],[MarketPhylo],[LL])","expr:LR_fcs":"P([FCS]|[Sarb],[Wuhan],[MarketPhylo],[NoHost],[Preadapt],[LL]) ÷ P([FCS]|[Sarb],[Wuhan],[MarketPhylo],[NoHost],[Preadapt],[ZW])","expr:LR_1":"[LR]([Sarb])","expr:LR_2":"[LR]([Wuhan], [Sarb])","expr:LR_3":"[LR]([NoHost], [Sarb], [Wuhan], [MarketPhylo])","expr:eNetLR":"[netLR]","expr:ePostOdds":"[postOdds]","expr:pLL_givenLLorZW":"P([LL]|[obsAll],[LL] ∨ [ZW])"},ax:{"ax:llZwExclusive":"P([LL], [ZW]) = 0","ax:pLL_sarb":"{expr:pLL_sarb} = 1","ax:pLL_wuhan":"{expr:pLL_wuhan} = 1","ax:pLL_noHost":"{expr:pLL_noHost} = 1","ax:LR_fcs":"{expr:LR_fcs} = 1"},form:{"form:fOddsPrior":"{expr:oddsPrior} = exp([svar:logOddsPrior])","form:fLR_1":"{expr:LR_1} = 1 ÷ [svar:pZW_sarb]","form:fLR_2":"{expr:LR_2} = 1 ÷ [svar:pZW_wuhan]","form:fLR_3":"{expr:LR_3} = 1 ÷ [svar:pZW_noHost]","form:fNetLR":"{expr:eNetLR} = {expr:LR_1} × {expr:LR_2} × [svar:LR_marketPhylo] × {expr:LR_3} × [svar:LR_preadapt] × [svar:LR_cggcggAndRePattern]","form:fPostOdds":"{expr:ePostOdds} = {expr:oddsPrior} × {expr:eNetLR}","form:fPLL":"{expr:pLL_givenLLorZW} = {expr:ePostOdds} ÷ (1 + {expr:ePostOdds})"},definedSym:{"definedSym:obsAll":"[Sarb] ∧ [Wuhan] ∧ [MarketPhylo] ∧ [NoHost] ∧ [Preadapt] ∧ [FCS] ∧ [CGGCGG] ∧ [REpattern]","definedSym:LR":"P(e|ec,[LL]) ÷ P(e|ec,[ZW])","definedSym:priorOdds":"P([LL]) ÷ P([ZW])","definedSym:cggcggAndRePattern":"[CGGCGG] ∧ [REpattern]","definedSym:netLR":"P([obsAll]|[LL]) ÷ P([obsAll]|[ZW])","definedSym:postOdds":"P([LL]|[obsAll]) ÷ P([ZW]|[obsAll])"}},h=[{id:"isym:LL",kind:"boolrv",longname:"labLeakDEFUSE",defn:"The pandemic virus originated from DEFUSE-style laboratory work (chimeric bat-coronavirus construction of the kind outlined in the DEFUSE proposal) and then leaked. [LL] is deliberately restricted to this narrow branch."},{id:"isym:ZW",kind:"boolrv",longname:"wildlifeZoonosis",defn:"The pandemic virus originated from natural wildlife zoonosis, a spillover from an animal reservoir into humans, with no laboratory involvement."},{id:"isym:Sarb",kind:"boolrv",longname:"Sarbecovirus",defn:"The pandemic was caused by a sarbecovirus, a virus in the SARS-related subgenus (the same broad group as the original SARS virus, SARS-CoV-1). This is about the pathogen type only; where it first spread is the separate Wuhan factor."},{id:"isym:Wuhan",kind:"boolrv",longname:"WuhanLocation",defn:"Given that the pathogen was a sarbecovirus, that its first human spread was in Wuhan specifically."},{id:"isym:MarketPhylo",kind:"boolrv",longname:"marketSpatialAndPhylogeneticClustering",defn:"The combined body of reported evidence consisting of (a) the spatial clustering of early confirmed cases and positive environmental samples around the Huanan Seafood Market (HSM), as analyzed by Worobey et al., and (b) the apparent two-lineage (A/B) viral phylogenetic pattern, interpreted by Pekar et al. as evidence of two independent spillovers most plausibly both linked to HSM. These are the two most-cited quantitative arguments for a market-specific zoonotic origin ([ZWM])."},{id:"isym:NoHost",kind:"boolrv",longname:"NoIntermediateHost",defn:"No intermediate wildlife host of the virus has been identified anywhere, despite extensive sampling."},{id:"isym:Preadapt",kind:"boolrv",longname:"HumanPreadaptation",defn:"The earliest sequenced strains showed unusually slow early adaptive (non-synonymous) evolution in humans compared with SARS-CoV-1, and much slower than the rapid evolution seen after SARS-CoV-2 later spilled from humans into minks and zoo animals; and from the outset they bound human ACE2 more strongly than the ACE2 of most candidate animal hosts."},{id:"isym:CGGCGG",kind:"boolrv",longname:"ArginineCodonPattern",defn:"The two adjacent arginines of the furin cleavage site are both encoded by CGG, the rarest of the six arginine codons in related natural viruses.",srcquotes:["srcquote:baltimoreCGGCGG"]},{id:"isym:REpattern",kind:"boolrv",longname:"RestrictionEnzymePattern",defn:"Cutting the genome with the restriction enzymes BsaI/BsmBI yields six segments, the longest just under about 8 kb; and at those cut sites the genome's sequence matches that of the virus's estimated natural relatives. (This is a compound observation: the segment pattern together with the site-sequence match.)"},{id:"isym:FCS",kind:"boolrv",longname:"FurinCleavageSite",defn:"The virus has a furin cleavage site at the S1/S2 junction of the spike, a feature absent in its known close relatives."},{id:"isym:pandemic",kind:"boolrv",longname:"pandemicOccurred",defn:"A human pandemic occurred. This is the selection condition under which the sequence features are observed at all, and matters for the furin-cleavage-site factor."},{id:"isym:ZL",kind:"boolrv",longname:"labHandlingOfNaturalVirus",defn:"Included for contrast: hypothesis NOT studied here. A natural, unmodified virus that reached people because of laboratory activities: sampling, collection, transport, storage, culturing, or other handling of viruses by a laboratory or its field workers. The virus itself is natural (not engineered); what makes this a lab-involved origin is that laboratory work, rather than ordinary ecological contact, is what brought it into contact with humans. An infection that merely happens to a laboratory worker through non-laboratory exposure (for example as an ordinary market customer) is not [ZL]; the laboratory activity must be part of the causal chain."},{id:"isym:ZWM",kind:"boolrv",longname:"zoonosisMarket",defn:"For broader context: The market sub-branch of [ZW]: the spillover reached humans via wildlife traded at a Wuhan market. Folded in rather than isolated here."},{id:"isym:ZWO",kind:"boolrv",longname:"zoonosisNonMarket",defn:"For broader context: The non-market sub-branch of [ZW]: the spillover reached humans by a route other than the Wuhan market. Folded in rather than isolated here."},{id:"isym:WIV",kind:"boolrv",longname:"labLeakWIV",defn:"For broader context: The sub-branch of [LL] in which the work was done at the Wuhan Institute of Virology. Folded in rather than isolated here."},{id:"isym:CCDC",kind:"boolrv",longname:"labLeakChineseCDC",defn:"For broader context: The sub-branch of [LL] in which the work was done at the Wuhan branch of the Chinese CDC. Folded in rather than isolated here."}],c=[{id:"ax:llZwExclusive",sexpr:["eq",["prob",["brvAnd","isym:LL","isym:ZW"]],0],defn:"The two hypotheses cannot both hold. They are not exhaustive, however, so the conclusion below is a forced choice between them rather than an unconditional probability of lab origin."},{id:"ax:pLL_sarb",sexpr:["eq","expr:pLL_sarb",1]},{id:"ax:pLL_wuhan",sexpr:["eq","expr:pLL_wuhan",1]},{id:"ax:pLL_noHost",sexpr:["eq","expr:pLL_noHost",1]},{id:"ax:LR_fcs",sexpr:["eq","expr:LR_fcs",1]}],u=[{id:"expr:logOddsPrior",sexpr:["log",["defnCall","definedSym:priorOdds"]]},{id:"expr:oddsPrior",sexpr:["defnCall","definedSym:priorOdds"]},{id:"expr:pZW_sarb",sexpr:["cond","isym:Sarb","isym:ZW"]},{id:"expr:pZW_wuhan",sexpr:["cond","isym:Wuhan","isym:Sarb","isym:ZW"]},{id:"expr:LR_marketPhylo",sexpr:["defnCall","definedSym:LR","isym:MarketPhylo",["list","isym:Sarb","isym:Wuhan"]]},{id:"expr:pZW_noHost",sexpr:["cond","isym:NoHost","isym:Sarb","isym:Wuhan","isym:MarketPhylo","isym:ZW"]},{id:"expr:LR_preadapt",sexpr:["defnCall","definedSym:LR","isym:Preadapt",["list","isym:Sarb","isym:Wuhan","isym:MarketPhylo","isym:NoHost"]]},{id:"expr:LR_cggcggAndRePattern",sexpr:["defnCall","definedSym:LR",["defnCall","definedSym:cggcggAndRePattern"],["list","isym:Sarb","isym:Wuhan","isym:MarketPhylo","isym:NoHost","isym:Preadapt","isym:FCS"]]},{id:"expr:pLL_sarb",sexpr:["cond","isym:Sarb","isym:LL"]},{id:"expr:pLL_wuhan",sexpr:["cond","isym:Wuhan","isym:Sarb","isym:LL"]},{id:"expr:pLL_noHost",sexpr:["cond","isym:NoHost","isym:Sarb","isym:Wuhan","isym:MarketPhylo","isym:LL"]},{id:"expr:LR_fcs",sexpr:["/",["cond","isym:FCS","isym:Sarb","isym:Wuhan","isym:MarketPhylo","isym:NoHost","isym:Preadapt","isym:LL"],["cond","isym:FCS","isym:Sarb","isym:Wuhan","isym:MarketPhylo","isym:NoHost","isym:Preadapt","isym:ZW"]]},{id:"expr:LR_1",sexpr:["defnCall","definedSym:LR","isym:Sarb",["list"]]},{id:"expr:LR_2",sexpr:["defnCall","definedSym:LR","isym:Wuhan",["list","isym:Sarb"]]},{id:"expr:LR_3",sexpr:["defnCall","definedSym:LR","isym:NoHost",["list","isym:Sarb","isym:Wuhan","isym:MarketPhylo"]]},{id:"expr:eNetLR",sexpr:["defnCall","definedSym:netLR"]},{id:"expr:ePostOdds",sexpr:["defnCall","definedSym:postOdds"]},{id:"expr:pLL_givenLLorZW",sexpr:["cond","isym:LL",["defnCall","definedSym:obsAll"],["brvOr","isym:LL","isym:ZW"]]}],m=[{id:"form:fOddsPrior",sexpr:["eq","expr:oddsPrior",["exp","svar:logOddsPrior"]],type_highlevel:"oddsratio"},{id:"form:fLR_1",sexpr:["eq","expr:LR_1",["/",1,"svar:pZW_sarb"]],type_highlevel:"oddsratio"},{id:"form:fLR_2",sexpr:["eq","expr:LR_2",["/",1,"svar:pZW_wuhan"]],type_highlevel:"oddsratio"},{id:"form:fLR_3",sexpr:["eq","expr:LR_3",["/",1,"svar:pZW_noHost"]],type_highlevel:"oddsratio"},{id:"form:fNetLR",sexpr:["eq","expr:eNetLR",["*","expr:LR_1","expr:LR_2","svar:LR_marketPhylo","expr:LR_3","svar:LR_preadapt","svar:LR_cggcggAndRePattern"]],type_highlevel:"oddsratio"},{id:"form:fPostOdds",sexpr:["eq","expr:ePostOdds",["*","expr:oddsPrior","expr:eNetLR"]],type_highlevel:"oddsratio"},{id:"form:fPLL",sexpr:["eq","expr:pLL_givenLLorZW",["/","expr:ePostOdds",["+",1,"expr:ePostOdds"]]],type_highlevel:"probability"}],f=[{id:"definedSym:obsAll",formal_defn:["brvAnd","isym:Sarb","isym:Wuhan","isym:MarketPhylo","isym:NoHost","isym:Preadapt","isym:FCS","isym:CGGCGG","isym:REpattern"],defn:"Conjunction of the observation features, in evidence-chain order.",always_inline:!1},{id:"definedSym:LR",formal_defn:["/",["cond",["param","e"],["param","ec"],"isym:LL"],["cond",["param","e"],["param","ec"],"isym:ZW"]],defn:"Conditional likelihood ratio for evidence e given the prior-evidence chain ec: >1 when the DEFUSE-style lab-leak account explains e better than wildlife zoonosis.",args:["e",{name:"ec",kind:"list"}],always_inline:!1},{id:"definedSym:priorOdds",formal_defn:["/",["prob","isym:LL"],["prob","isym:ZW"]],defn:"Prior on the origin being lab-related rather than wildlife zoonosis",always_inline:!1},{id:"definedSym:cggcggAndRePattern",formal_defn:["brvAnd","isym:CGGCGG","isym:REpattern"],defn:"Conjunction of the CGG-CGG codon pattern and the restriction-enzyme segment pattern, elicited as one joint factor from v7 on.",always_inline:!1},{id:"definedSym:netLR",formal_defn:["/",["cond",["defnCall","definedSym:obsAll"],"isym:LL"],["cond",["defnCall","definedSym:obsAll"],"isym:ZW"]],defn:"Net likelihood ratio over the evidence chain. Equals the product of the per-factor conditional LRs by the chain rule.",always_inline:!1},{id:"definedSym:postOdds",formal_defn:["/",["cond","isym:LL",["defnCall","definedSym:obsAll"]],["cond","isym:ZW",["defnCall","definedSym:obsAll"]]],defn:"Posterior odds. Equals [priorOdds] × [netLR].",always_inline:!1}],g=[],p="mcovidB8",b=JSON.parse(`[{"id":"framing:attribution","defn":"This judgement problem is strongly based on Michael Weissman's \\"An Inconvenient Probability v5.13\\" Substack essay","flabel":"version","static_anchor":"root","framing_target":null},{"id":"framing:versionNotes","defn":"Changes from previous version:\\n\\t- The conclusion is now stated as P([LL] | obsAll, [LL] ∨ [ZW]) — a probability renormalized over just the two modeled hypotheses — rather than as P([LL] | obsAll). The computed number is unchanged; the conclusion formula was always Z/(1+Z), and that quantity equals P([LL] | obsAll) only if [LL] and [ZW] exhaust the possible origins, which they do not. A new axiom states that [LL] and [ZW] are mutually exclusive, which is the one thing the renormalization does require.\\n\\t- A bug in Dustin's AI authoring instructions resulted in compute formulas (thankfully redundant, in this case) being hidden from the markdown prompts given to AIs. Bug since it was an unjustified difference between the AI and human views of the judgment problem. Wasn't caught because none of the AI estimators complained, instead just getting the math from other definitions. Previous versions in this problem's timeline now show the reduced set in the webapp, so you can be the judge of \\"redundant\\" if you wish.\\n\\t- Eliminated some bias that leaked into should-be-unbiased framing notes, and removed mention of source argument except in a \\"version\\" framing note to try to limit contamination for AIs.\\n\\t- Simplified framing note POV labels and added some explainer.\\n\\t- Redundantly clarified zoonotic-lab [ZL] vs leak-lab [LL] hypotheses.\\n\\t- The fixed axiom setting the furin-cleavage-site likelihood ratio to 1 now conditions on the evidence preceding it in the chain, as every other factor already did. No computed value changes. The correction matters because the net likelihood ratio omits this factor rather than multiplying by it, and that omission is exact only for the chain-conditioned ratio, which is what the chain rule multiplies.\\n\\t- Clarified \\"roughly-independent\\" in the summary.","flabel":"version","static_anchor":"root","framing_target":null},{"id":"framing:implicitPandemicConditioning","defn":"All conditional probabilities are implicitly conditioned on [pandemic]; it is built into P(⋯|⋯). Making it explicit would involve adding e.g. a K background knowledge Bayesian proposition that only appears on the right side of every conditional probability expression, cluttering every formula.","flabel":"meta","static_anchor":"root","framing_target":null},{"id":"framing:llZwNotExhaustive","defn":"[LL] and [ZW] as defined here are not the only possible origin routes: a natural, unmodified virus could also have reached people via laboratory sampling or handling ([ZL]) rather than through a designed-and-leaked construct. The reported conclusion is therefore {expr:pLL_givenLLorZW} — a forced choice between these two specific accounts — not an unconditional probability that the origin was lab-related in the broadest sense. The author's own view (Appendix 5 of the source essay) is that folding [ZL] back in would not shrink the lab-origin side: since [ZL] is itself a research-related channel, including it can only add to the lab-vs-nature odds, not subtract from them, so the narrow [LL]-vs-[ZW] framing used here is if anything conservative about total lab involvement, even though it is silent on the [LL]-vs-[ZL] split specifically.","flabel":"meta","static_anchor":"root","framing_target":null},{"id":"framing:featureSelectionCaveat","defn":"The sequence-level features modeled here ([CGGCGG], [REpattern], and the general idea of pre-adaptation) were originally proposed by researchers who were specifically looking for signs of engineering; candidate signatures that were examined and found non-diagnostic are, by construction, not part of this evidence chain, since only the diagnostic-looking ones became notable enough to write about. This kind of search-and-report asymmetry can inflate the apparent net evidence for the hypothesis that motivated the search, in a way that per-factor uncertainty about any single estimate does not by itself capture. The author states he omits only factors he judges genuinely small or uncertain, and does not omit any factor he thinks favors zoonosis (see the prior-odds section); the concern here is a further, upstream one, about which candidate signatures got proposed and investigated at all, not about how any single one was then estimated.","flabel":"ZW","static_anchor":"root","framing_target":null},{"id":"framing:fcsSelectionBias","defn":"Author's choice to make this likelihood ratio exactly 1 (too uncertain to sign) only makes sense under the [pandemic] selection-bias explained above.","flabel":"clarification","static_anchor":"ax:LR_fcs","framing_target":null},{"id":"framing:cggcggRePatternJointElicitation","defn":"From this version on, [CGGCGG] and [REpattern] are elicited as a single joint likelihood ratio rather than as four separate probabilities (a P(·|LL) and a P(·|ZW) for each). Trial feedback on the four-svar version repeatedly flagged these two sequence-design signatures as the clearest case where independent sampling of separate factors can't represent a real correlation: both are evidence about whether the genome was deliberately designed, so a scenario in which one signature turns out to be misleading (a misspecified null model, an overlooked natural mechanism) plausibly makes the other misleading too. Asking for one combined belief distribution lets you put real weight on that shared-failure-mode directly — for instance, non-trivial density near LR=1 for 'the whole engineered-look reading of this region is wrong' — without needing an explicit correlation mechanism between separate svars.","flabel":"meta","static_anchor":"svar:LR_cggcggAndRePattern","framing_target":null},{"id":"framing:cggcggDerivation","defn":"Michael derives the two sides of the CGGCGG sub-factor differently. His zoonosis-side figure comes from the single-step-insertion path rather than from whole-genome codon frequencies: treating the furin site as one random long nucleotide insertion, whose codon frequencies differ from the rest of the genome, a tabulation across related coronaviruses put the fraction of arginine pairs that come out CGGCGG at about 0.023 (14 of 616), which he treats as an upper limit on the zoonosis probability with a spread of roughly a factor of two either way. His lab-origin figure is a deliberately wide bracket rather than a pinned number: the floor is 1/36 (both arginines landing on CGG by chance among the six synonymous codons), the ceiling is 1 (a designer choosing CGGCGG for certain), and lacking a good reference set of comparable lab inserts he takes the geometric mean of those limits, about 1/6, under a uniform prior on the log between 1/36 and 1. Combined, his numbers imply a CGGCGG-alone likelihood ratio of about (1/6)/0.023 ≈ 7.","flabel":"author_estimate","static_anchor":"svar:LR_cggcggAndRePattern","srcquotes":["srcquote:gadboitInsert"],"framing_target":null},{"id":"framing:cggcggMechanism","defn":"Background on the mechanism: each amino acid is specified by three-nucleotide codons, and arginine has six synonymous codons, of which CGG is one. Codon optimization is the routine practice, when a gene is synthesized for expression in a particular host, of substituting the synonymous codons that host translates most efficiently. The evidential question is whether the specific choice of CGG for both arginines is better explained by that laboratory practice or by natural sequence evolution.","flabel":"clarification","static_anchor":"isym:CGGCGG","framing_target":null},{"id":"framing:cggcggLabCase","defn":"Michael reads the double-CGG as genuine if fuzzy support for a lab origin. CGG is the rarest arginine codon in the natural relatives, yet synthetic genes built for human hosts are routinely codon-optimized toward the common human codons, and CGG is the most common arginine codon in humans; the Pfizer and Moderna teams recoded almost all of their arginine codons to CGG. There was also a concrete engineering motive to choose this exact pair: CGGCGG creates a restriction-enzyme site that lets a researcher quickly confirm the inserted furin site has not been lost in cell culture, a point raised by Deigin.","flabel":"LL","static_anchor":"isym:CGGCGG","srcquotes":["srcquote:vaccineCGGoptimization","srcquote:deiginREmarker"],"framing_target":null},{"id":"framing:cggcggNaturalInsert","defn":"The strongest zoonosis-consistent reading, raised to Michael by the pseudonymous analyst Guy Gadboit, is that the furin site arrived as a single natural insertion of the whole twelve-nucleotide piece. Long insertions carry codon frequencies unlike the rest of the genome, because the inserted piece can be read in a different frame or direction, so among random long inserts in related coronaviruses about 2.3% of arginine pairs come out CGGCGG, far above the roughly 0.07% you would guess from whole-genome frequencies. On this account the double-CGG is unremarkable for a natural insert. A detail that cuts the same way: the vaccine designers, though they favored CGG everywhere else, pointedly did not use CGGCGG for their own arginine pair.","flabel":"ZW","static_anchor":"isym:CGGCGG","srcquotes":["srcquote:vaccineAvoidedCGGCGG"],"framing_target":null},{"id":"framing:cggcggNarrowModel","defn":"The author himself flags that a factor like this can be overstated: a large likelihood ratio computed inside a narrow model (here, assumptions about which codons a designer would choose) tends to shrink once one allows for the ways nature and people step around such models. He applies that caution explicitly to his own lab-favoring CGGCGG factor.","flabel":"ZW","static_anchor":"isym:CGGCGG","srcquotes":["srcquote:narrowModelCaution"],"framing_target":null},{"id":"framing:routeBvsAuthorMethod","defn":"This exposition departs from the source author's own bookkeeping in a way worth stating once. He works entirely in log-odds: each factor is a point estimate of a log-likelihood-ratio with a standard error, high-uncertainty factors are hierarchically down-weighted, and the results are summed. This version instead carries each factor as a full belief distribution over its own quantity (a probability, an odds ratio, or, for the prior, log-odds) and integrates them jointly by Monte Carlo, with no separate down-weighting step; the pull toward even odds that his down-weighting produced emerges here from the joint integral. That is why the per-factor notes (when enabled!) describe his estimates in each quantity's own units rather than reproducing his summed-logit machinery.","flabel":"meta","static_anchor":"root","framing_target":null},{"id":"framing:routeA","defn":"This is the 'B' line. A separate, more faithful rendering of his exact arithmetic is kept on the 'A' line, which may be available as mcovidA in the top-right selector.","flabel":"version","framing_target":"framing:routeBvsAuthorMethod","static_anchor":"root"},{"id":"framing:pointProductNotFaithful","defn":"One concrete consequence: multiplying together the central (point) value of every factor yield a naive posterior, which is not the intended answer. That product neither down-weights the uncertain factors (as the source author does) nor accounts for the expected value of a product of uncertain quantities not being the product of their expected values, which this version does. The faithful result comes from integrating the full joint distribution over all factors, which pulls the odds back toward even.","flabel":"clarification","static_anchor":null,"framing_target":"framing:routeBvsAuthorMethod"},{"id":"framing:preset","defn":"Accordingly the saved author preset omits a point-estimate answer and reports only the distribution-based one.","flabel":"version","static_anchor":null,"framing_target":"framing:pointProductNotFaithful"},{"id":"framing:priorDerivation","defn":"The source author builds the prior from two rates. On the zoonosis side, a tabulation of emerging pathogens in China implies roughly a one-in-three chance per year of some significant new zoonotic pathogen, making zoonosis the conventional null. On the lab side, restricting to DEFUSE-style work at one Wuhan lab, he estimates about 1/100 per year if such work was underway and about a 50% chance it was, giving roughly 1/200. The ratio is about 1/70 in favor of lab origin, i.e. log-odds -4.2, and he assigns it a wide uncertainty (a factor of about 10, so plus or minus 2.3 in log-odds) that he calls the single most important uncertainty in the whole analysis.","flabel":"author_estimate","static_anchor":"svar:logOddsPrior","srcquotes":["srcquote:priorLabLeakRates","srcquote:priorZoonosisNull"],"framing_target":null},{"id":"framing:priorZoonosisIsNull","defn":"The starting point favors zoonosis heavily, and for good reason: essentially every pandemic of the modern era arose naturally, wildlife spillovers are common, and the historical base rate for a research-related pandemic is very low. On this view zoonosis is the boring default that the evidence must overcome, and one is entitled to a stiff prior against a lab origin before looking at any specifics of this virus.","flabel":"ZW","static_anchor":"svar:logOddsPrior","srcquotes":["srcquote:priorZoonosisNull"],"framing_target":null},{"id":"framing:priorLabRiskWasRecognized","defn":"The author's case for a non-negligible lab prior is that expert institutions were warning, before the pandemic, that exactly this kind of accident was a serious risk. A 2019 Global Preparedness Monitoring Board report urged that biosafety become a national priority for countries funding pathogen work that could seed a respiratory pandemic, and pre-Covid analyses put the per-lab yearly chance of a human-transmissible leak at a fraction of a percent, higher for work at reduced biosafety levels. He argues those warnings only make sense if the prior probability of a damaging leak was already appreciable.","flabel":"LL","static_anchor":"svar:logOddsPrior","srcquotes":["srcquote:priorLabLeakWarnings","srcquote:priorLabLeakRates"],"framing_target":null},{"id":"framing:priorConsensusZoonosis","defn":"The prevailing position among relevant scientific bodies and most virologists has been that a natural zoonotic origin is more likely than a lab leak, and several intelligence assessments reached only low confidence in either direction. Someone weighting that institutional consensus more heavily than this author does would set a lower prior on lab origin than his one-in-seventy.","flabel":"ZW","static_anchor":"svar:logOddsPrior","framing_target":null},{"id":"framing:priorConsensusRebuttal","defn":"This confuses the prior odds with other people's posterior conclusions. The prior here is a base-rate question: before weighing any specifics of this virus, how often would a pandemic of this kind in this setting come from research versus from nature? That should be built from the frequencies of past lab leaks and natural spillovers, not from a survey of what experts currently believe about this particular case. Folding others' all-things-considered verdicts into your prior double-counts their evidence; their conclusions belong as comparisons to your posterior.","flabel":"LL","static_anchor":null,"framing_target":"framing:priorConsensusZoonosis"},{"id":"framing:sarbDerivation","defn":"For the zoonosis side the author estimates how often an emerging pandemic pathogen would be a sarbecovirus specifically, using the base rate of about one sarbecovirus (the original SARS) among nineteen notable pathogens that emerged in China over the period, i.e. roughly one such outbreak per fifty years. He notes the figure would be lower still if one also required the observed degree of sequence difference from SARS-CoV-1. The lab side is fixed at probability 1 by construction, because the DEFUSE-style branch already specifies a sarbecovirus.","flabel":"author_estimate","static_anchor":"svar:pZW_sarb","srcquotes":["srcquote:sarbOnePerFifty"],"framing_target":null},{"id":"framing:sarbLLBuiltIn","defn":"The author reads 'it was a sarbecovirus' as favoring the lab branch almost for free: the DEFUSE proposal specifically described collecting and modifying bat sarbecoviruses, so under that branch a sarbecovirus is expected with near certainty, whereas among natural emerging pathogens it is one uncommon category out of many.","flabel":"LL","static_anchor":"svar:pZW_sarb","framing_target":null},{"id":"framing:sarbNaturalIsReal","defn":"Sarbecoviruses do emerge naturally: SARS-CoV-1 was itself a wildlife sarbecovirus spillover, and the bat reservoir for this whole viral group is large and active. That a new pandemic virus turned out to be a sarbecovirus is only mildly surprising under zoonosis and reflects genuine natural risk rather than anything specific to a laboratory.","flabel":"ZW","static_anchor":"svar:pZW_sarb","framing_target":null},{"id":"framing:wuhanDerivation","defn":"Given a sarbecovirus, the author estimates the chance its first human spread would be in Wuhan specifically from Wuhan's share of the relevant population: about 0.7% of China's people and about 1.1% of the urban population, so roughly 1 in 100, uncertain by about a factor of two. He notes the market sub-hypothesis fares far worse, because Wuhan's share of the national wildlife trade is far smaller than its population share, on the order of 1 in 1000 or less.","flabel":"author_estimate","static_anchor":"svar:pZW_wuhan","srcquotes":["srcquote:wuhanPopulationShare","srcquote:wuhanTradeShare"],"framing_target":null},{"id":"framing:worobeyCoincidenceArg","defn":"The strongest single argument for a natural market origin (which the author himself calls the only major zoonosis argument that looks plausible on first inspection) is Worobey et al.'s: among the hundreds of places an outbreak could first have been detected, the Huanan market being the first ascertained site would be a striking coincidence, on the order of 1 in 400, unless the market really was the spillover site. The clustering of early cases around the market, and reports of the virus in animal-stall samples, are offered as direct support.","flabel":"ZW","static_anchor":"svar:LR_marketPhylo","srcquotes":["srcquote:worobeyCoincidence"],"framing_target":null},{"id":"framing:pekarTwoLineageArg","defn":"The second major zoonosis-favoring argument is phylogenetic. Pekar et al. modeled the early viral lineages and reported Bayesian odds of roughly 60:1 favoring two independent spillovers to humans (most plausibly both linked to the Huanan market) over a single spillover with a shared most-recent common ancestor. That two-spillover reading was then widely repeated as close to settled — for instance by two of the paper's own authors, writing that the analysis found the origin question essentially resolved.","flabel":"ZW","static_anchor":"svar:LR_marketPhylo","srcquotes":["srcquote:rasmussenWorobey99pct"],"framing_target":null},{"id":"framing:worobeyAscertainmentBiasDetail","defn":"Michael's central rebuttal of the market-clustering argument is that Worobey et al.'s own data contain internal evidence of the proximity-based ascertainment bias he argues drove the apparent clustering: cases were preferentially found and reported when they had a known link to the market, which mechanically pulls the 'linked' cluster toward the market regardless of where the true spillover occurred. He reports that in the Worobey data itself, cases with no known market link resided on average *closer* to the market than cases with a documented market link — the opposite of what simple market-centered spread would predict — a difference he and others find statistically significant and have since confirmed with several independent tests (kernel-density mapping, permutation tests). He calls this his one original contribution to the origins debate.","flabel":"LL","static_anchor":"svar:LR_marketPhylo","srcquotes":["srcquote:worobeyAscertainmentDistances"],"framing_target":null},{"id":"framing:pekarMathErrorRebuttal","defn":"Michael also argues the Pekar et al. two-spillover odds do not survive scrutiny on their own terms, independent of any market-proximity question: he identifies specific mathematical and coding errors in their published analysis, most fundamentally that they compared the two hypotheses using different, unbalanced observational requirements (analogous to computing separate probabilities of 'drives a car' for one suspect and 'drives a blue Toyota' for another, then comparing them as if they answered the same question). He reports that simply correcting the acknowledged errors reverses the paper's headline conclusion, favoring a single spillover over two; this correction now appears as an eLetter attached to the published paper and, more fully, in a peer-reviewed article in Econ Journal Watch.","flabel":"LL","static_anchor":"svar:LR_marketPhylo","srcquotes":["srcquote:pekarCorrectedOdds"],"framing_target":null},{"id":"framing:marketPhyloLimitedRelevance","defn":"Separately from whether the underlying analyses hold up, the author argues this evidence has limited bearing on [LL] vs. [ZW] specifically even taken at face value. A market spillover and a two-lineage pattern are primarily evidence about which zoonotic route occurred (a market spillover [ZWM] vs. some other route [ZWO], or one spillover vs. two), not about whether a laboratory was involved at all: a lab could equally well have handled or leaked multiple related strains (DEFUSE itself proposed working with collections of closely related viral strains, not a single purified one), so a genuine two-lineage finding would not, on its own, discriminate lab origin from wildlife origin.","flabel":"LL","static_anchor":"svar:LR_marketPhylo","srcquotes":["srcquote:lineageNotLLvsZWdiagnostic"],"framing_target":null},{"id":"framing:marketPhyloWhyModeled","defn":"This factor is new from this version on. In earlier versions the market-clustering and phylogenetic evidence appeared only as prose attached to the Wuhan-location factor, with no way to give it a numeric weight of its own; trial feedback repeatedly named that omission as the single biggest reason a computed posterior read as more extreme than an estimator's all-things-considered belief. The notes here give both the raw case usually made from this evidence and the author's detailed rebuttal of it, so you can weigh them yourself rather than the exposition's silence standing in for an answer.","flabel":"version","static_anchor":"svar:LR_marketPhylo","framing_target":null},{"id":"framing:wuhanMainstreamMarket","defn":"Both the market-clustering case and the two-lineage case were published in leading venues (Science) by large, credentialed research groups, and both continue to be cited by working scientists and science journalism as settled or close to it — for example the Foreign Affairs piece describing the two-spillover finding as a near-certainty. A reader who trusts that publication and citation record over the author's single-author rebuttals (one of which, on the Pekar arithmetic, is now itself peer-reviewed) would treat this evidence as real support for zoonosis rather than as neutralized.","flabel":"ZW","static_anchor":"svar:LR_marketPhylo","framing_target":null},{"id":"framing:noHostDerivation","defn":"Under zoonosis the author estimates the probability that no intermediate wildlife host would ever be found, calibrating against other recently emerged coronaviruses: intermediate hosts were identified for most of them, though not all. Taking a value consistent with those precedents, and noting the search for this virus has been unusually intense (more than 80,000 animals tested), he arrives at a likelihood ratio of roughly 4 in favor of lab origin, since a lab origin predicts no wildlife host with certainty.","flabel":"author_estimate","static_anchor":"svar:pZW_noHost","srcquotes":["srcquote:lancetNoHost"],"framing_target":null},{"id":"framing:noHostFavorsLab","defn":"For the two most comparable recent spillovers, SARS-CoV-1 and MERS, intermediate wildlife hosts were found; for SARS-CoV-2, despite testing tens of thousands of animals, none has been found anywhere. The author treats that persistent absence as a real if modest mark against a wildlife route, which by definition would have left an animal reservoir to find.","flabel":"LL","static_anchor":"svar:pZW_noHost","srcquotes":["srcquote:lancetNoHost"],"framing_target":null},{"id":"framing:noHostOtherCoronas","defn":"An intermediate host has not been found for every human coronavirus either: for HCoV-NL63, and arguably HKU1, no proximal host was ever pinned down, and hosts can take years to identify or go unsearched for milder viruses. Some argue SARS-CoV-1's presumed market hosts were themselves infected by humans rather than the source. Absence of a found host is weak evidence when searches are incomplete and the true reservoir may be a bat rather than a traded animal.","flabel":"ZW","static_anchor":"svar:pZW_noHost","framing_target":null},{"id":"framing:preadaptDerivation","defn":"This is the one factor the author declines to split into separate numerator and denominator; he gives a single likelihood ratio of about 3 in favor of lab origin for the bundle of early-adaptation features. He calls this conservative and attaches only a small uncertainty, meant to signal that much weaker values are implausible rather than that much stronger ones are.","flabel":"author_estimate","static_anchor":"svar:LR_preadapt","srcquotes":["srcquote:holmesPreadapted"],"framing_target":null},{"id":"framing:preadaptFavorsLab","defn":"The author's case is that SARS-CoV-2 behaved from the outset as if it had already adapted to humans, in contrast to SARS-CoV-1: its early human evolution was several times slower, its furin region barely evolved in human cell culture, and it bound human ACE2 better than the ACE2 of leading candidate animal hosts, evolving rapidly only after it later spilled back into minks and zoo animals. Passage through human-airway cell cultures or humanized mice, as DEFUSE described, would explain such pre-adaptation; a fresh wildlife spillover, on his view, would not.","flabel":"LL","static_anchor":"svar:LR_preadapt","srcquotes":["srcquote:holmesNoTrace"],"framing_target":null},{"id":"framing:preadaptBatAncestor","defn":"Apparent pre-adaptation is also consistent with descent from an already well-adapted bat ancestor: BANAL sarbecoviruses found in Laos bind human ACE2 well without any lab involvement, so a fairly human-competent ancestor could exist in nature. On a direct-from-bat account this same ancestor supplies the pre-adaptation while also explaining why no intermediate wildlife host was ever found, since none would be needed. Early slow evolution can additionally reflect a founder effect and the very low case-ascertainment of the first weeks, so the sample may simply have missed the adaptive period rather than there having been none.","flabel":"ZW","static_anchor":"svar:LR_preadapt","srcquotes":["srcquote:banalBinding","srcquote:directBatPreadapt"],"framing_target":null},{"id":"framing:preadaptAscertainment","defn":"Mainstream analyses generally do not treat pre-adaptation as strong evidence, arguing that the earliest, unsampled transmission chains are exactly where any rapid human adaptation would have occurred, and that impressions of unprecedented fitness were early and subjective. Weighting that objection heavily would pull this factor toward 1, i.e. no evidence either way.","flabel":"ZW","static_anchor":"svar:LR_preadapt","framing_target":null},{"id":"framing:fcsSelectionBiasDerivation","defn":"The author sets this likelihood ratio to exactly 1 on purpose. The mere presence of a furin cleavage site is often cited as strong lab evidence because the site is absent in close relatives and DEFUSE proposed adding one, but he argues that reasoning ignores selection: we are only examining this virus because it caused a pandemic, and a furin site may be near-necessary for that, so conditioning on a pandemic having occurred removes the site's diagnostic value. He judges the residual factor too uncertain to sign, and neutrally leaves it at 1.","flabel":"author_estimate","static_anchor":"ax:LR_fcs","srcquotes":["srcquote:fcsSelectionBias"],"framing_target":null},{"id":"framing:fcsCouldFavorLab","defn":"Many observers, including authors of the main paper arguing against a lab origin, found the furin site itself suggestive of engineering, and the author notes that no other sarbecovirus in any non-bat host has acquired a furin site despite opportunity, which could be read as weak evidence against an easy natural route. He deliberately declines to draw a factor from this, to avoid the selection-bias trap and double-counting, so a neutral reader should treat the setting of 1 as a conservative choice rather than a finding that the site is uninformative.","flabel":"LL","static_anchor":"ax:LR_fcs","srcquotes":["srcquote:fcsGarry"],"framing_target":null},{"id":"framing:fcsNaturalOrigin","defn":"Furin cleavage sites arise naturally in many coronaviruses, and the specific SARS-CoV-2 site (amino acids RRAR) matches a common human protease-site motif rather than an obviously engineered one; it is even identical to a sequence in a human protein. The site could have been acquired in a single natural insertion. On the zoonosis view the furin site is a fitness feature that any pandemic-capable sarbecovirus would plausibly need, which is exactly why conditioning on a pandemic makes it non-diagnostic.","flabel":"ZW","static_anchor":"ax:LR_fcs","srcquotes":["srcquote:proximalRRAR"],"framing_target":null},{"id":"framing:rePatternDerivation","defn":"Michael derives the two sides of the REpattern sub-factor differently. For the natural side he estimates how often a coronavirus would, by chance, be cuttable into six segments each under about 8 kb by the BsaI/BsmBI enzyme pair: random-placement simulations and direct counts across roughly a thousand related viruses (in which this virus is essentially the only exact match) put this near 0.0015 to 0.004, and he conservatively uses 0.004 — a pattern-only upper bound on the full compound event, since also requiring the natural-relative sequence match at the cut sites could only lower it further. For the lab side he starts from about 0.2, allowing that a DEFUSE-style build might not keep exactly six segments, the same enzyme pair, or the cut sites intact in the final product, then multiplies by roughly the 0.2 chance that a reverse-genetics designer would also happen to use site sequences already seen in natural relatives (a feature actually observed in this virus), reaching about 0.04. Combined, his numbers imply a REpattern-alone likelihood ratio of about 0.04/0.004 = 10.","flabel":"author_estimate","static_anchor":"svar:LR_cggcggAndRePattern","srcquotes":["srcquote:rePatternRare"],"framing_target":null},{"id":"framing:rePatternCompoundNote","defn":"The two sides of this factor are, strictly, about slightly different events. The lab-side probability is for the full compound observation: the six-segment BsaI/BsmBI pattern together with the match, at those sites, to the sequences of estimated natural relatives. The natural-side probability is estimated for the segment pattern alone and used as a conservative upper bound on the compound event, because adding the sequence-match requirement can only make the natural probability smaller. So the likelihood ratio here is, if anything, understated in favor of a natural origin.","flabel":"clarification","static_anchor":"isym:REpattern","framing_target":null},{"id":"framing:rePatternFavorsLab","defn":"The author regards this as perhaps the cleanest sequence factor, because the cut pattern has nothing to do with viral fitness, so a natural virus's matching it is pure coincidence. The BsaI/BsmBI six-segment scheme was independently flagged as engineering-like before a leaked DEFUSE draft was found to describe assembling the genome from six contiguous cDNA pieces linked by unique restriction sites, a prediction he treats as strikingly confirmed.","flabel":"LL","static_anchor":"isym:REpattern","srcquotes":["srcquote:defuseSixPieces"],"framing_target":null},{"id":"framing:rePatternNatural","defn":"Critics argue the pattern can occur naturally and is not a reliable fingerprint: the BsaI/BsmBI sites are not conserved, this virus's variants have gained and lost such sites over time, and related viruses do occasionally fall in or near the same range. On this reading a six-segment pattern at the pandemic's start is an unremarkable draw from natural variation rather than a signature of assembly.","flabel":"ZW","static_anchor":"isym:REpattern","srcquotes":["srcquote:wuPatternNatural"],"framing_target":null},{"id":"framing:rePatternDriftExpectedUnderLL","defn":"The 'not conserved over time' critique gets the direction of the prediction backwards. Lab origin does not predict that the six-segment cut-site pattern would persist across the whole subsequent phylogeny — it predicts the pattern was present in the initial engineered sequence and would erode under ordinary mutation once no longer under any selective pressure to maintain it, since the pattern has no effect on viral fitness. That matches what is observed: no betacoronavirus lineage sampled before the pandemic shows the pattern, and it has been gradually lost across sampled descendant variants since. Non-conservation over time is therefore consistent with, and expected under, the pattern having been imposed once at the start, not evidence against it.","flabel":"LL","static_anchor":"isym:REpattern","srcquotes":["srcquote:driftExpectedUnderLL"],"framing_target":null},{"id":"framing:fPLLMathHelp","defn":"Expands to LL-posterior ÷ (LL-posterior + ZW-posterior). By axiom [ax:llZwExclusive] that denominator is exactly P([LL] ∨ [ZW] | [obsAll]). Dividing by it renormalizes onto [LL] ∨ [ZW], which is what the left side's conditioning records. It is less than 1, since [LL] and [ZW] are not exhaustive.\\nNote [postOdds] is a ratio between the two hypotheses, so anything common to both cancels; conditioning it on [LL] ∨ [ZW] would change nothing. Turning that ratio into a single probability is where it stops cancelling.","flabel":"math-help","static_anchor":"form:fPLL","framing_target":null},{"id":"framing:LRHelp","defn":"Displays as LR(X,Y,Z), but read as LR(X|Y,Z).","flabel":"math-help","static_anchor":"definedSym:LR","framing_target":null}]`),y=JSON.parse(`[{"id":"srcquote:baltimoreCGGCGG","defn":"> ...the SC2 FCS has two adjacent arginines (Arg's), each coded for by the nucleotide codon CGG. CGG is the least common of the 6 Arg codons in all related natural viruses. CGG is only used for ~2.6% of the Arg's in the rest of SC2. None of the other 40 Arg's on the spike protein use CGG.","attribution":"‹‹source argument››"},{"id":"srcquote:gadboitInsert","defn":"> The pattern that Garry noted could be typical for a lab insertion but could also occur by a one-step natural insertion of the whole 12 nt piece. ... an initial tabulation of the fraction of ArgArg's that would be coded CGGCGG in such random long insertions in a collection of related coronaviruses has been calculated by Gadboit to be 0.0227 (14 of 616 potential ArgArg codes in inserts found at least twice), much larger than the values estimated from the rest of the sequence or from actual ArgArg coding in related viruses.","attribution":"An Inconvenient Probability: 17-_The_FCS_and_its_neighbors"},{"id":"srcquote:vaccineCGGoptimization","defn":"> The designers of both vaccines considered CGG as the optimal codon in the CGN codon family and recoded almost all CGN codons to CGG.","attribution":"\\"Detailed Dissection and Critical Evaluation of the Pfizer/BioNTech and Moderna mRNA Vaccines\\" (ResearchGate), quoted in An Inconvenient Probability"},{"id":"srcquote:deiginREmarker","defn":"> Deigin has pointed out another reason that a researcher inserting coding for ArgArg might specifically choose CGGCGG -- it provides a marker for a standard, easy, restriction enzyme test allowing the researcher to know if that insertion is still present or has been lost, an important consideration since FCS's tend to get lost in cell culture.","attribution":"An Inconvenient Probability: 35_Appendix_4_FCS_uses"},{"id":"srcquote:vaccineAvoidedCGGCGG","defn":"> Although both designers were fond of CGG, neither used CGGCGG for the ArgArg pair, indicating that they had some reason to avoid it, perhaps connected to occasional translational errors that might be particularly important to avoid in vaccines although less important for viral fitness.","attribution":"An Inconvenient Probability: 35_Appendix_4_FCS_uses"},{"id":"srcquote:priorLabLeakRates","defn":"> Another careful pre-Covid analysis of experiences of labs using very good but not extreme biosafety practices, BSL-3, estimated that the yearly chance of a major human-transmissible leak was around 0.2% per lab to 1% per full-time lab worker. For a large lab doing much of its work at a much lower safety level (BSL-2) the chances would be higher.","attribution":"An Inconvenient Probability: 05-_Prior_odds"},{"id":"srcquote:priorZoonosisNull","defn":"> From that rate one can roughly estimate that the probability of a significant new pathogen in any year, e.g. 2019, would be P0(2019, ZW) = ~ 1/3. That's higher than the probability of some widespread disease emerging from a research incident in any year, justifying the general view that if one must choose a favored 'null hypothesis' for a generic new pathogen the choice would be ZW.","attribution":"An Inconvenient Probability: 05-_Prior_odds"},{"id":"srcquote:priorLabLeakWarnings","defn":"> Were a high-impact respiratory pathogen to emerge, either naturally or as the result of accidental or deliberate release, it would likely have significant public health, economic, social, and political consequences. ... Biosafety needs to become a national-level political priority, particularly for countries that are funding research with the potential to result in accidents with pathogens that could initiate high-impact respiratory pandemics.","attribution":"Global Preparedness Monitoring Board / Johns Hopkins Center for Health Security, Sept. 2019"},{"id":"srcquote:sarbOnePerFifty","defn":"> Here for the ZW account we have in the combined prior and likelihood factor in effect ignored the non-sarbecovirus diseases and just used an estimate of one sarbecovirus outbreak per about 50 years.","attribution":"An Inconvenient Probability: 06-_Where_and_What_Sarbecovirus_starting_in_Wuhan"},{"id":"srcquote:wuhanPopulationShare","defn":"> since Wuhan has ~0.7% of China's population and ~1.1% of the urban population P(Wuhan|sarbecovirus, ZW) =~0.01, perhaps uncertain to about a factor of 2.","attribution":"An Inconvenient Probability: 06-_Where_and_What_Sarbecovirus_starting_in_Wuhan"},{"id":"srcquote:wuhanTradeShare","defn":"> The tiny fraction of the wildlife trade that is found in Wuhan means that the specific market version ZWM has much steeper odds to overcome than non-market ZW accounts would have.","attribution":"An Inconvenient Probability: 06-_Where_and_What_Sarbecovirus_starting_in_Wuhan"},{"id":"srcquote:worobeyCoincidence","defn":"> Worobey et al. argue that since there were hundreds of plausible superspreading locations it would require a remarkable coincidence, with probability ~1/400, for a possible spillover site, HSM, to be the first ascertained spreading site unless it were the actual spillover site. ... Of the major arguments (other than priors) supporting ZW, I think this is the only one that looks plausible on first inspection.","attribution":"An Inconvenient Probability: 10--_Phylogeny_and_location_Pekar_et_al_and_Worobey_et_al"},{"id":"srcquote:lineageNotLLvsZWdiagnostic","defn":"> there is no obvious reason why getting two closely related strains from having an MRCA in some other animal a few transmission cycles before two spillovers to humans would say much about whether the other animal was a standard humanized mouse in a lab or an unspecified wildlife animal in a market.","attribution":"An Inconvenient Probability: 10--_Phylogeny_and_location_Pekar_et_al_and_Worobey_et_al"},{"id":"srcquote:worobeyAscertainmentDistances","defn":"> (ii) cases linked directly to the Huanan market (median distance 5.74 km…), and (iii) cases with no evidence of a direct link to the Huanan market (median distance 4.00 km…). The cases with no known link to the market on average resided closer to the market than the cases with links to the market (P = 0.029).","attribution":"Worobey et al., quoted in An Inconvenient Probability: 28--_Worobey"},{"id":"srcquote:pekarCorrectedOdds","defn":"> simply fixing the clear mathematical and programming errors of Pekar et al. leaves N=1 more probable than N=2, a conclusion opposite to the key result proclaimed in the paper.","attribution":"An Inconvenient Probability: 29--_Pekar"},{"id":"srcquote:rasmussenWorobey99pct","defn":"> we find a roughly 99 percent probability that SARS-CoV-2 spilled over at least twice","attribution":"Rasmussen and Worobey, Foreign Affairs, quoted in An Inconvenient Probability: 29--_Pekar"},{"id":"srcquote:farrarEscherLoop","defn":"> That tight case definition resulted in an Escher's loop of misguided circular reasoning: testing only those people with a link to the market created the illusion that the market was the source of disease, because everyone testing positive had been there. In reality, the net should have been cast wider...","attribution":"Jeremy Farrar, Spike"},{"id":"srcquote:gaoMarketVictim","defn":"> At first, we assumed the seafood market might have the virus, but now the market is more like a victim. The novel coronavirus had existed long before.","attribution":"George Gao, then head of the China CDC, Global Times"},{"id":"srcquote:lancetNoHost","defn":"> Despite the testing of more than 80000 samples from a range of wild and farm animal species in China collected between 2015 and March, 2020, no cases of SARS-CoV-2 infection have been identified.","attribution":"Lancet COVID-19 Commission"},{"id":"srcquote:holmesPreadapted","defn":"> It is indeed striking that this virus is so closely related to SARS yet is behaving so differently. Seems to have been pre-adapted for human spread since the get go.","attribution":"Eddie Holmes, Proximal Origin correspondence (2/10/2020)"},{"id":"srcquote:holmesNoTrace","defn":"> Bottom line is that the Wuhan virus is beautifully adapted to human transmission but we have no trace of that evolutionary history in nature.","attribution":"Eddie Holmes, Proximal Origin correspondence (2/3/2020)"},{"id":"srcquote:banalBinding","defn":"> Since then several bat sarbecoviruses, dubbed BANAL, have been reported to be found in Laos. Some have good human ACE2 binding although none have been found to have an FCS.","attribution":"An Inconvenient Probability: 16-_Pre-adaptation_combined_with_intermediate_hosts"},{"id":"srcquote:fcsSelectionBias","defn":"> We are only discussing SC2 because it caused a pandemic. So far as we know having an FCS may be common in the subset of hypothetical related viruses that are capable of causing a human pandemic. In other words even though for some generic sarbecovirus P(FCS|ZW) is much less than one, P(FCS|ZW, pandemic) need not be.","attribution":"An Inconvenient Probability: 17-_The_FCS_and_its_neighbors"},{"id":"srcquote:fcsGarry","defn":"> I really can't think of a plausible natural scenario where you get from the bat virus or one very similar to it to \\\\[SC2\\\\] where you insert exactly 4 amino acids 12 nucleotide that all have to be added at the exact same time to gain this function ... Of course in the lab it would be easy to generate the perfect 12 base insert that you wanted.","attribution":"Robert Garry, House Oversight hearing"},{"id":"srcquote:proximalRRAR","defn":"> The FCS of human ENaC a has the amino acid sequence RRAR'SVAS ... that is perfectly identical with the FCS of SARS-CoV-2.","attribution":"Harrison and Sachs, PNAS"},{"id":"srcquote:rePatternRare","defn":"> Of 1316 betacoronaviruses, none except SC2 meet the (6,<8knt) criterion. Only 14 meet the broader (5-8, <8knt) criterion. For alphacoronaviruses, 4 of 1378 meet the (6, <8knt) criterion and 28 met the broader (5 to 8, <8knt) criterion. Combining the two types, one estimates P(6,<8knt|Z) = 4/2694= 0.0015.","attribution":"An Inconvenient Probability: 18-_Restriction_Enzyme_Segment_Pattern"},{"id":"srcquote:defuseSixPieces","defn":"> We will identify the best consensus candidate and synthesize the genome using commercial vendors (e.g., BioBasic, etc.), as six contiguous cDNA pieces linked by unique restriction endonuclease sites that do not disturb the coding sequence, but allow for full length genome assembly.","attribution":"DEFUSE proposal draft, via Emily Kopp / U.S. Right to Know"},{"id":"srcquote:wuPatternNatural","defn":"> These results showed that this endonuclease map is not highly conserved and dynamic in SARS-CoV-2 and reflects its evolutionary diversity in alpha- and betacoronavirus. ... Thus, the pattern of BsmBI/BsaI sites is not appropriate to indicate the origin of SARS-CoV-2.","attribution":"F. Wu, quoted in An Inconvenient Probability: 18-_Restriction_Enzyme_Segment_Pattern"},{"id":"srcquote:driftExpectedUnderLL","defn":"> That during subsequent evolution the RE site pattern drifts away from the one characteristic of synthetic chimeras fits perfectly with the LL claim that it was imposed on the initial sequence by lab engineering along DEFUSE lines. LL predicts that the pattern would be present in the initial sequence but quite unlikely before and after. There are no known prior instances in betacoronaviruses and the pattern is gradually being lost in new variants, as expected.","attribution":"Michael Weissman, personal communication to the author of this exposition, July 2026"},{"id":"srcquote:narrowModelCaution","defn":"> The issue is analogous to the one I ran into for the LL-favoring CGGCGG factor. A very large odds calculation can be obtained within a narrow model. Both nature and people have ways of stepping around the narrow models, giving much lower odds.","attribution":"An Inconvenient Probability: 26_Appendix_1_Other_Bayesian_analyses"},{"id":"srcquote:directBatPreadapt","defn":"> The reports of Laotian BANAL bat sarbecoviruses with good human ACE2 binding but lacking an FCS suggest a way for getting good preadaptation while skipping intermediate wildlife hosts altogether.","attribution":"An Inconvenient Probability: 36_Appendix_5_Research_spillover_of_a_zoonotic_virus"}]`),v={options:a,config:i,svar_list:o,svar:n,tchoice:r,layout:s,textchunk:l,display:d,isym:h,ax:c,expr:u,form:m,definedSym:f,textdefn:g,aid:p,framing:b,srcquote:y},w=JSON.parse('[{"name_or_pseudoname":"source author (Route B)","notoriety":"","occupation":"","affiliation":"","plainnum":[{"label":"uniform prior","aid":"mcovidB8","prompt_file_basename":"","aopts":{},"cparam_values":{},"count":1,"trials":[{"point":{},"bounds":{},"sample":{"logOddsPrior":"uniform(-8.183716857, -0.2162831426)","pZW_sarb":"lognormal(-2.65, 0.8)","pZW_wuhan":"lognormal(-4.6, 0.7)","LR_marketPhylo":"lognormal(0, 1.5)","pZW_noHost":"lognormal(-1.3, 0.6)","LR_preadapt":"lognormal(1.1, 0.5)","LR_cggcggAndRePattern":"lognormal(4.3, 2.0)"},"trial_choices":{"agreeMarketPhyloDiscount":true},"reasoning":{"logOddsPrior":"The author builds the prior from two base rates. On the zoonosis side, a tabulation of emerging pathogens in China implies roughly a one-in-three chance per year of some significant new zoonotic pathogen — the conventional null. On the lab side, restricting to DEFUSE-style work at one Wuhan lab, he estimates about 1/100 per year if such work was underway times about a 50% chance it was, giving roughly 1/200 per year. Combined, the prior odds on lab origin are about 1/70 (zoonosis roughly 70× more likely a priori), i.e. log-odds ≈ -4.2, to which he attaches a wide uncertainty — a factor of about 10, about ±2.3 in log-odds — that he calls the single most important uncertainty in the whole analysis. This preset renders that prior as a bounded, tail-free `uniform(-8.18, -0.22)`, whose midpoint is -4.2 and whose standard deviation (half-width ÷ √3) equals 2.3 — the same center and spread as the Gaussian and t(3) presets, but with no tails, the most conservative of the three.","pZW_sarb":"P(Sarb | ZW): under zoonosis, how often would an emerging pandemic pathogen be a sarbecovirus specifically? The author uses a base rate of about one sarbecovirus (the original SARS) among roughly nineteen notable pathogens that emerged in China over the period — about one such outbreak per fifty years — and notes the figure would be lower still if one also required the observed degree of sequence difference from SARS-CoV-1. The lab side is fixed at 1 by construction (the DEFUSE-style branch already specifies a sarbecovirus), so this probability is essentially the whole sarbecovirus factor. Rendered as `lognormal(-2.65, 0.8)` (median ≈ 0.07, i.e. a likelihood ratio of ≈ 14 for lab origin), broad (σ = 0.8) to reflect the thin reference class.","pZW_wuhan":"P(Wuhan | Sarb, ZW): given a sarbecovirus, the author estimates the chance its first human spread would be in Wuhan specifically from Wuhan\'s share of the relevant population — about 0.7% of China\'s people and about 1.1% of its urban population, so roughly 1 in 100, uncertain by about a factor of two. He notes the market sub-hypothesis fares far worse, because Wuhan\'s share of the national wildlife trade is far below its population share (on the order of 1 in 1000 or less) — the evidence bearing specifically on that market sub-hypothesis is what the new LR_marketPhylo factor below now carries. Rendered as `lognormal(-4.6, 0.7)` (median ≈ 0.01), the σ giving the stated factor-of-two spread.","LR_marketPhylo":"LR(MarketPhylo | Sarb, Wuhan): new in v7. The author does not give a single pinned number for this combined factor — he instead argues at length that both underlying analyses are individually undermined (an ascertainment-bias argument for Worobey et al.\'s case-location data, mathematical/coding-error corrections for Pekar et al.\'s two-spillover claim) and that even a fully-credited version of this evidence would mainly bear on which zoonotic sub-route occurred (market vs. non-market) rather than on lab origin vs. zoonosis directly, concluding elsewhere that the market sub-hypothesis specifically comes out unfavored once everything is weighed. Rendered here as a distribution centered at LR=1 (non-diagnostic — his implied net position on the LL-vs-ZW question specifically) with substantial two-sided spread, `lognormal(0, 1.5)`: wide enough to reach down toward the raw published claims (if one trusts Worobey/Pekar over his rebuttals) and up to a mild lab-favoring reading (if one weights his ascertainment-bias finding, which runs opposite to the direction simple market-centered spread would predict).","pZW_noHost":"P(NoHost | Sarb, Wuhan, MarketPhylo, ZW): the probability that no intermediate wildlife host would ever be found under zoonosis. The author calibrates against other recently emerged coronaviruses — intermediate hosts were identified for most, though not all — and notes the unusually intense search here (more than 80,000 animals tested). Since a lab origin predicts no wildlife host with certainty, this yields a likelihood ratio of roughly 4 for lab origin. Rendered as `lognormal(-1.3, 0.6)` (median ≈ 0.27, i.e. LR ≈ 3.7).","LR_preadapt":"LR(Preadapt): the one factor the author declines to split into separate numerator and denominator, giving instead a single likelihood ratio of about 3 for lab origin over the bundle of early human-adaptation features (early human evolution several times slower than SARS-CoV-1, the furin region barely evolving in cell culture, and stronger human-ACE2 binding than the leading candidate animal hosts). He calls this conservative and attaches only a small uncertainty, meant to signal that much weaker values are implausible rather than that much stronger ones are. Rendered as `lognormal(1.1, 0.5)` (median ≈ 3.0).","LR_cggcggAndRePattern":"LR(CGGCGG ∧ REpattern | …): from v7 this factor is elicited jointly rather than as four separate probabilities (see the version framing note). The author\'s own component numbers multiply to a combined point value of about (1/6)/0.023 × 0.04/0.004 ≈ 7 × 10 = 74 (logits 2.0 + 2.3 = 4.3: CGGCGG\'s pLL of ≈1/6 over pZW of ≈0.023, times REpattern\'s pLL of ≈0.04 over pZW of 0.004). Rendered as `lognormal(4.3, 2.0)`, keeping his combined median but with a σ deliberately wider than a naive combination of his two components\' individual uncertainties (≈1.4) would give, to hold real density near LR=1 for the shared-failure-mode scenario several trial agents flagged: if the \'engineered-look\' reading of one signature is wrong (a misspecified null model, an overlooked natural mechanism), the other plausibly shares the same error, which independent per-component sampling cannot represent."}}],"precomputed":{}},{"label":"Gaussian prior","aid":"mcovidB8","prompt_file_basename":"","aopts":{},"cparam_values":{},"count":1,"trials":[{"point":{},"bounds":{},"sample":{"logOddsPrior":"normal(-4.2, 2.3)","pZW_sarb":"lognormal(-2.65, 0.8)","pZW_wuhan":"lognormal(-4.6, 0.7)","LR_marketPhylo":"lognormal(0, 1.5)","pZW_noHost":"lognormal(-1.3, 0.6)","LR_preadapt":"lognormal(1.1, 0.5)","LR_cggcggAndRePattern":"lognormal(4.3, 2.0)"},"trial_choices":{"agreeMarketPhyloDiscount":true},"reasoning":{"logOddsPrior":"The author builds the prior from two base rates. On the zoonosis side, a tabulation of emerging pathogens in China implies roughly a one-in-three chance per year of some significant new zoonotic pathogen — the conventional null. On the lab side, restricting to DEFUSE-style work at one Wuhan lab, he estimates about 1/100 per year if such work was underway times about a 50% chance it was, giving roughly 1/200 per year. Combined, the prior odds on lab origin are about 1/70 (zoonosis roughly 70× more likely a priori), i.e. log-odds ≈ -4.2, to which he attaches a wide uncertainty — a factor of about 10, about ±2.3 in log-odds — that he calls the single most important uncertainty in the whole analysis. This preset renders that prior directly as `normal(-4.2, 2.3)` — his central log-odds and his stated ±2.3 uncertainty, with light Gaussian tails.","pZW_sarb":"P(Sarb | ZW): under zoonosis, how often would an emerging pandemic pathogen be a sarbecovirus specifically? The author uses a base rate of about one sarbecovirus (the original SARS) among roughly nineteen notable pathogens that emerged in China over the period — about one such outbreak per fifty years — and notes the figure would be lower still if one also required the observed degree of sequence difference from SARS-CoV-1. The lab side is fixed at 1 by construction (the DEFUSE-style branch already specifies a sarbecovirus), so this probability is essentially the whole sarbecovirus factor. Rendered as `lognormal(-2.65, 0.8)` (median ≈ 0.07, i.e. a likelihood ratio of ≈ 14 for lab origin), broad (σ = 0.8) to reflect the thin reference class.","pZW_wuhan":"P(Wuhan | Sarb, ZW): given a sarbecovirus, the author estimates the chance its first human spread would be in Wuhan specifically from Wuhan\'s share of the relevant population — about 0.7% of China\'s people and about 1.1% of its urban population, so roughly 1 in 100, uncertain by about a factor of two. He notes the market sub-hypothesis fares far worse, because Wuhan\'s share of the national wildlife trade is far below its population share (on the order of 1 in 1000 or less) — the evidence bearing specifically on that market sub-hypothesis is what the new LR_marketPhylo factor below now carries. Rendered as `lognormal(-4.6, 0.7)` (median ≈ 0.01), the σ giving the stated factor-of-two spread.","LR_marketPhylo":"LR(MarketPhylo | Sarb, Wuhan): new in v7. The author does not give a single pinned number for this combined factor — he instead argues at length that both underlying analyses are individually undermined (an ascertainment-bias argument for Worobey et al.\'s case-location data, mathematical/coding-error corrections for Pekar et al.\'s two-spillover claim) and that even a fully-credited version of this evidence would mainly bear on which zoonotic sub-route occurred (market vs. non-market) rather than on lab origin vs. zoonosis directly, concluding elsewhere that the market sub-hypothesis specifically comes out unfavored once everything is weighed. Rendered here as a distribution centered at LR=1 (non-diagnostic — his implied net position on the LL-vs-ZW question specifically) with substantial two-sided spread, `lognormal(0, 1.5)`: wide enough to reach down toward the raw published claims (if one trusts Worobey/Pekar over his rebuttals) and up to a mild lab-favoring reading (if one weights his ascertainment-bias finding, which runs opposite to the direction simple market-centered spread would predict).","pZW_noHost":"P(NoHost | Sarb, Wuhan, MarketPhylo, ZW): the probability that no intermediate wildlife host would ever be found under zoonosis. The author calibrates against other recently emerged coronaviruses — intermediate hosts were identified for most, though not all — and notes the unusually intense search here (more than 80,000 animals tested). Since a lab origin predicts no wildlife host with certainty, this yields a likelihood ratio of roughly 4 for lab origin. Rendered as `lognormal(-1.3, 0.6)` (median ≈ 0.27, i.e. LR ≈ 3.7).","LR_preadapt":"LR(Preadapt): the one factor the author declines to split into separate numerator and denominator, giving instead a single likelihood ratio of about 3 for lab origin over the bundle of early human-adaptation features (early human evolution several times slower than SARS-CoV-1, the furin region barely evolving in cell culture, and stronger human-ACE2 binding than the leading candidate animal hosts). He calls this conservative and attaches only a small uncertainty, meant to signal that much weaker values are implausible rather than that much stronger ones are. Rendered as `lognormal(1.1, 0.5)` (median ≈ 3.0).","LR_cggcggAndRePattern":"LR(CGGCGG ∧ REpattern | …): from v7 this factor is elicited jointly rather than as four separate probabilities (see the version framing note). The author\'s own component numbers multiply to a combined point value of about (1/6)/0.023 × 0.04/0.004 ≈ 7 × 10 = 74 (logits 2.0 + 2.3 = 4.3: CGGCGG\'s pLL of ≈1/6 over pZW of ≈0.023, times REpattern\'s pLL of ≈0.04 over pZW of 0.004). Rendered as `lognormal(4.3, 2.0)`, keeping his combined median but with a σ deliberately wider than a naive combination of his two components\' individual uncertainties (≈1.4) would give, to hold real density near LR=1 for the shared-failure-mode scenario several trial agents flagged: if the \'engineered-look\' reading of one signature is wrong (a misspecified null model, an overlooked natural mechanism), the other plausibly shares the same error, which independent per-component sampling cannot represent."}}],"precomputed":{}},{"label":"t(3) prior","aid":"mcovidB8","prompt_file_basename":"","aopts":{},"cparam_values":{},"count":1,"trials":[{"point":{},"bounds":{},"sample":{"logOddsPrior":"t-trunc(-4.2, 1.327905619, 3, -54.8, 2.7)","pZW_sarb":"lognormal(-2.65, 0.8)","pZW_wuhan":"lognormal(-4.6, 0.7)","LR_marketPhylo":"lognormal(0, 1.5)","pZW_noHost":"lognormal(-1.3, 0.6)","LR_preadapt":"lognormal(1.1, 0.5)","LR_cggcggAndRePattern":"lognormal(4.3, 2.0)"},"trial_choices":{"agreeMarketPhyloDiscount":true},"reasoning":{"logOddsPrior":"The author builds the prior from two base rates. On the zoonosis side, a tabulation of emerging pathogens in China implies roughly a one-in-three chance per year of some significant new zoonotic pathogen — the conventional null. On the lab side, restricting to DEFUSE-style work at one Wuhan lab, he estimates about 1/100 per year if such work was underway times about a 50% chance it was, giving roughly 1/200 per year. Combined, the prior odds on lab origin are about 1/70 (zoonosis roughly 70× more likely a priori), i.e. log-odds ≈ -4.2, to which he attaches a wide uncertainty — a factor of about 10, about ±2.3 in log-odds — that he calls the single most important uncertainty in the whole analysis. This preset renders that prior as a heavy-tailed `t-trunc(-4.2, 1.328, 3, -54.8, 2.7)`: the same center (-4.2) and same nominal standard deviation (2.3 = scale × √3) as the other two, but Student-t (df 3) tails, truncated to hold the upper (pro-lab) tail below about +2.7 log-odds. Because the posterior is sensitive to the prior\'s tails, this is the most tail-heavy of the three renderings.","pZW_sarb":"P(Sarb | ZW): under zoonosis, how often would an emerging pandemic pathogen be a sarbecovirus specifically? The author uses a base rate of about one sarbecovirus (the original SARS) among roughly nineteen notable pathogens that emerged in China over the period — about one such outbreak per fifty years — and notes the figure would be lower still if one also required the observed degree of sequence difference from SARS-CoV-1. The lab side is fixed at 1 by construction (the DEFUSE-style branch already specifies a sarbecovirus), so this probability is essentially the whole sarbecovirus factor. Rendered as `lognormal(-2.65, 0.8)` (median ≈ 0.07, i.e. a likelihood ratio of ≈ 14 for lab origin), broad (σ = 0.8) to reflect the thin reference class.","pZW_wuhan":"P(Wuhan | Sarb, ZW): given a sarbecovirus, the author estimates the chance its first human spread would be in Wuhan specifically from Wuhan\'s share of the relevant population — about 0.7% of China\'s people and about 1.1% of its urban population, so roughly 1 in 100, uncertain by about a factor of two. He notes the market sub-hypothesis fares far worse, because Wuhan\'s share of the national wildlife trade is far below its population share (on the order of 1 in 1000 or less) — the evidence bearing specifically on that market sub-hypothesis is what the new LR_marketPhylo factor below now carries. Rendered as `lognormal(-4.6, 0.7)` (median ≈ 0.01), the σ giving the stated factor-of-two spread.","LR_marketPhylo":"LR(MarketPhylo | Sarb, Wuhan): new in v7. The author does not give a single pinned number for this combined factor — he instead argues at length that both underlying analyses are individually undermined (an ascertainment-bias argument for Worobey et al.\'s case-location data, mathematical/coding-error corrections for Pekar et al.\'s two-spillover claim) and that even a fully-credited version of this evidence would mainly bear on which zoonotic sub-route occurred (market vs. non-market) rather than on lab origin vs. zoonosis directly, concluding elsewhere that the market sub-hypothesis specifically comes out unfavored once everything is weighed. Rendered here as a distribution centered at LR=1 (non-diagnostic — his implied net position on the LL-vs-ZW question specifically) with substantial two-sided spread, `lognormal(0, 1.5)`: wide enough to reach down toward the raw published claims (if one trusts Worobey/Pekar over his rebuttals) and up to a mild lab-favoring reading (if one weights his ascertainment-bias finding, which runs opposite to the direction simple market-centered spread would predict).","pZW_noHost":"P(NoHost | Sarb, Wuhan, MarketPhylo, ZW): the probability that no intermediate wildlife host would ever be found under zoonosis. The author calibrates against other recently emerged coronaviruses — intermediate hosts were identified for most, though not all — and notes the unusually intense search here (more than 80,000 animals tested). Since a lab origin predicts no wildlife host with certainty, this yields a likelihood ratio of roughly 4 for lab origin. Rendered as `lognormal(-1.3, 0.6)` (median ≈ 0.27, i.e. LR ≈ 3.7).","LR_preadapt":"LR(Preadapt): the one factor the author declines to split into separate numerator and denominator, giving instead a single likelihood ratio of about 3 for lab origin over the bundle of early human-adaptation features (early human evolution several times slower than SARS-CoV-1, the furin region barely evolving in cell culture, and stronger human-ACE2 binding than the leading candidate animal hosts). He calls this conservative and attaches only a small uncertainty, meant to signal that much weaker values are implausible rather than that much stronger ones are. Rendered as `lognormal(1.1, 0.5)` (median ≈ 3.0).","LR_cggcggAndRePattern":"LR(CGGCGG ∧ REpattern | …): from v7 this factor is elicited jointly rather than as four separate probabilities (see the version framing note). The author\'s own component numbers multiply to a combined point value of about (1/6)/0.023 × 0.04/0.004 ≈ 7 × 10 = 74 (logits 2.0 + 2.3 = 4.3: CGGCGG\'s pLL of ≈1/6 over pZW of ≈0.023, times REpattern\'s pLL of ≈0.04 over pZW of 0.004). Rendered as `lognormal(4.3, 2.0)`, keeping his combined median but with a σ deliberately wider than a naive combination of his two components\' individual uncertainties (≈1.4) would give, to hold real density near LR=1 for the shared-failure-mode scenario several trial agents flagged: if the \'engineered-look\' reading of one signature is wrong (a misspecified null model, an overlooked natural mechanism), the other plausibly shares the same error, which independent per-component sampling cannot represent."}}],"precomputed":{}}],"plaincode":[]}]'),_={"form:fOddsPrior":{typeHighlevel:"oddsratio",params:["logOddsPrior"],point(e){return t(e[0])},bounds(e){return{lo:t(e[0][0]),hi:t(e[0][1])}},boundsTightness:"tight"},"form:fLR_1":{typeHighlevel:"oddsratio",params:["pZW_sarb"],point(e){return 1/e[0]},bounds(e){return{lo:1/e[0][1],hi:1/e[0][0]}},boundsTightness:"tight"},"form:fLR_2":{typeHighlevel:"oddsratio",params:["pZW_wuhan"],point(e){return 1/e[0]},bounds(e){return{lo:1/e[0][1],hi:1/e[0][0]}},boundsTightness:"tight"},"form:fLR_3":{typeHighlevel:"oddsratio",params:["pZW_noHost"],point(e){return 1/e[0]},bounds(e){return{lo:1/e[0][1],hi:1/e[0][0]}},boundsTightness:"tight"},"form:fNetLR":{typeHighlevel:"oddsratio",params:["pZW_sarb","pZW_wuhan","LR_marketPhylo","pZW_noHost","LR_preadapt","LR_cggcggAndRePattern"],point(e){return 1/e[0]*1/e[1]*e[2]*1/e[3]*e[4]*e[5]},bounds(e){return{lo:1/e[0][1]*1/e[1][1]*e[2][0]*1/e[3][1]*e[4][0]*e[5][0],hi:1/e[0][0]*1/e[1][0]*e[2][1]*1/e[3][0]*e[4][1]*e[5][1]}},boundsTightness:"tight"},"form:fPostOdds":{typeHighlevel:"oddsratio",params:["logOddsPrior","pZW_sarb","pZW_wuhan","LR_marketPhylo","pZW_noHost","LR_preadapt","LR_cggcggAndRePattern"],point(e){return t(e[0])*1/e[1]*1/e[2]*e[3]*1/e[4]*e[5]*e[6]},bounds(e){return{lo:t(e[0][0])*1/e[1][1]*1/e[2][1]*e[3][0]*1/e[4][1]*e[5][0]*e[6][0],hi:t(e[0][1])*1/e[1][0]*1/e[2][0]*e[3][1]*1/e[4][0]*e[5][1]*e[6][1]}},boundsTightness:"tight"},"form:fPLL":{typeHighlevel:"probability",params:["logOddsPrior","pZW_sarb","pZW_wuhan","LR_marketPhylo","pZW_noHost","LR_preadapt","LR_cggcggAndRePattern"],point(e){return t(e[0])*1/e[1]*1/e[2]*e[3]*1/e[4]*e[5]*e[6]/(1+t(e[0])*1/e[1]*1/e[2]*e[3]*1/e[4]*e[5]*e[6])},bounds(e){return{lo:1-1/(1+t(e[0][0])*1/e[1][1]*1/e[2][1]*e[3][0]*1/e[4][1]*e[5][0]*e[6][0]),hi:1-1/(1+t(e[0][1])*1/e[1][0]*1/e[2][0]*e[3][1]*1/e[4][0]*e[5][1]*e[6][1])}},boundsTightness:"tight"}},L="";function k(){return!0}const S={jpdefn:v,adhocPresets:w,plainnumResults:[],plaincodeResults:[],richcodeResults:[],formRegistry:_,cparamComboFilter:k,cparamFilterDescription:L};export{S as manifest};
